const item = $input.first();
const json = item.json;

// Initialize Lists
let price = "N/A";
let ema20_hist = [];
let ema50_hist = [];
let rsi_hist = [];

// Grab data from previous nodes in the chain
const nodePrice = $('Get Price').first().json;
const nodeEma20 = $('Get EMA20').first().json;
const nodeEma50 = $('Get EMA50').first().json;
const nodeRsi   = $('Get RSI').first().json;

// 1. Current Live Price
if (nodePrice) price = nodePrice.price;

// 2. EMA 20 History (Last 5 candles)
if (nodeEma20 && nodeEma20.values) {
    // Change slice(0,3) to slice(0,5)
    ema20_hist = nodeEma20.values.slice(0,5).map(v => v.ema);
}

// 3. EMA 50 History (Last 5 candles)
if (nodeEma50 && nodeEma50.values) {
    ema50_hist = nodeEma50.values.slice(0,5).map(v => v.ema);
}

// 4. RSI History (Last 5 candles)
if (nodeRsi && nodeRsi.values) {
    rsi_hist = nodeRsi.values.slice(0,5).map(v => v.rsi);
}

// Output
return [{
  json: {
    market_data: {
      symbol: "XAUUSD",
      current_price: price,
      trend_momentum: {
        ema20_last5: ema20_hist, 
        ema50_last5: ema50_hist,
        rsi_last5: rsi_hist
      }
    }
  }
}];

// 1. Get the input
const item = $input.first();
const json = item.json;

// --- FIND AI RESPONSE ---
function findAiResponse(obj) {
  if (!obj) return null;
  if (typeof obj === 'string' && (obj.includes('"signal":') || obj.includes("market_notes"))) return obj;
  if (typeof obj === 'object') {
    for (const key in obj) {
      const result = findAiResponse(obj[key]);
      if (result) return result;
    }
  }
  return null;
}

const rawText = findAiResponse(json);

// Safety fallback
if (!rawText) return [{ json: { text: "⚠ Waiting for data..." } }];

// 2. Clean and Parse
const clean = rawText.replace(/json|/g, '').trim();
let data;
try {
  data = JSON.parse(clean);
} catch (e) {
  // Try to repair simple JSON errors
  try {
     const fixed = clean.substring(clean.indexOf('{'), clean.lastIndexOf('}') + 1);
     data = JSON.parse(fixed);
  } catch (err2) {
     return [{ json: { text: "⚠ JSON Error" } }];
  }
}

// --- THE NEW "WAIT" FILTER ---
// If signal is WAIT, we force the numbers to be dashes
if (data.signal === "WAIT") {
  data.entry = "-";
  data.stop_loss = "-";
  data.take_profit = "-";
  data.confidence = "-"; 
} else {
  // If BUY/SELL, ensure we have values or fallback to N/A
  data.entry = data.entry || data.entry_price || "N/A";
  data.stop_loss = data.stop_loss || data.sl || "N/A";
  data.take_profit = data.take_profit || data.tp || "N/A";
}

// 3. Build Final Message
const finalMessage = `📊 XAUUSD Signal (5min)

Recommendation: ${data.signal} ${data.signal == 'BUY' ? '🟢' : data.signal == 'SELL' ? '🔴' : '⚪'}
Confidence: ${data.confidence}

Entry: ${data.entry}
Stop Loss: ${data.stop_loss}
Take Profit: ${data.take_profit}

📝 Market Notes:
${data.market_notes || data.analysis || "No notes."}`;

return [{ json: { text: finalMessage } }];
